#!/usr/bin/env bash
set -euo pipefail
command -v python3 >/dev/null 2>&1 || { echo '请先安装 Python 3.9+。' >&2; exit 1; }
# Read the embedded program from fd 3, keeping stdin available for configuration.
exec python3 /dev/fd/3 "$@" 3<<'SSH_TOOL_FEISHU_INSTALLER_PY'
