_BUNDLE_SHA256 = 'b6d6f2a2c09257aab5aa6d88c277dfb98d3cd65101ad389152d101b8e6cefbbc'
SERVICE = 'ssh-tool-feishu-agent.service'
SCOPES = ['im:message.p2p_msg:readonly', 'im:message:send_as_bot', 'im:message:readonly']
PERMISSIONS = {'scopes': {'tenant': SCOPES, 'user': []}}
FILES = {'agent.py', 'feishu_auto.py', 'requirements.txt', 'p2p-agent-amd64', 'p2p-agent-arm64', 'LICENSE.pion'}
QR_REGISTRATION = r'''
import json, os, sys, tempfile, webbrowser
from pathlib import Path
import lark_oapi as lark

def show_authorization(info):
    print('\n请打开下面的飞书授权链接，登录/扫码并确认创建专用应用：', flush=True)
    print(info['url'], flush=True)
    print('确认页应只有消息接收、机器人发送和消息读取三项权限；请核对后确认。', flush=True)
    try:
        webbrowser.open(info['url'])
    except webbrowser.Error:
        pass

try:
    result = lark.register_app(
        on_qr_code=show_authorization,
        app_preset={'name': 'SSH Tool P2P', 'desc': '本机 P2P 连接信令'},
        addons={'preset': False,
                'scopes': {'tenant': ['im:message.p2p_msg:readonly', 'im:message:send_as_bot', 'im:message:readonly'], 'user': []},
                'events': {'items': {'tenant': ['im.message.receive_v1']}}},
        create_only=True,
    )
    if not result.get('client_id') or not result.get('client_secret'):
        raise ValueError('missing credentials')
    target = Path(sys.argv[1])
    with tempfile.NamedTemporaryFile('w', dir=target.parent, delete=False, encoding='utf-8') as stream:
        os.chmod(stream.name, 0o600)
        json.dump({'app_id': result['client_id'], 'app_secret': result['client_secret']}, stream)
    os.replace(stream.name, target)
except Exception:
    print('飞书扫码授权未完成。请检查网络、授权是否取消/过期及企业是否允许创建应用，然后重新执行。', file=sys.stderr)
    sys.exit(1)
'''


def paths():
    home = Path.home()
    return (home / '.ssh_tool/feishu', home / '.config/ssh-tool-app/feishu-agent.json',
            home / '.config/systemd/user' / SERVICE)


def payload():
    if _BUNDLE is None:
        root = Path(__file__).resolve().parents[1]
        return {'agent.py': (root / 'deploy/feishu/agent.py').read_bytes(),
                'feishu_auto.py': (root / 'deploy/feishu/feishu_auto.py').read_bytes(),
                'requirements.txt': (root / 'deploy/feishu/requirements.txt').read_bytes(),
                'LICENSE.pion': (root / 'native/p2p/LICENSE.pion').read_bytes(),
                **{f'p2p-agent-{arch}': (root / f'assets/p2p/agent-linux-{arch}').read_bytes()
                   for arch in ('amd64', 'arm64')}}
    encoded = base64.b64decode(_BUNDLE, validate=True)
    if hashlib.sha256(encoded).hexdigest() != _BUNDLE_SHA256:
        raise RuntimeError('安装包校验失败，请重新获取完整脚本。')
    with zipfile.ZipFile(io.BytesIO(encoded)) as archive:
        if set(archive.namelist()) != FILES or any(item.file_size > 32 * 1024 * 1024 for item in archive.infolist()):
            raise RuntimeError('安装包内容无效。')
        return {name: archive.read(name) for name in FILES}


def write_private_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile('w', dir=path.parent, delete=False, encoding='utf-8') as stream:
            temporary = stream.name
            os.chmod(temporary, 0o600)
            json.dump(value, stream, ensure_ascii=False, indent=2)
            stream.write('\n')
        os.replace(temporary, path)
    finally:
        if temporary and os.path.exists(temporary):
            os.unlink(temporary)


def yes(label, default=False):
    answer = input(f"{label} {'[Y/n]' if default else '[y/N]'}: ").strip().lower()
    return default if not answer else answer in ('y', 'yes')


def feishu_request(path, data=None, token=None):
    headers = {'Content-Type': 'application/json; charset=utf-8'}
    if token:
        headers['Authorization'] = 'Bearer ' + token
    request = urllib.request.Request('https://open.feishu.cn/open-apis/' + path,
        data=json.dumps(data).encode() if data is not None else None, headers=headers)
    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            result = json.load(response)
    except (urllib.error.URLError, ValueError):
        raise RuntimeError('无法校验飞书配置，请检查网络和凭据后重新执行。') from None
    if result.get('code') != 0:
        raise RuntimeError(f"飞书校验未通过（code={result.get('code')}），请检查凭据、机器人能力及应用发布状态。")
    return result


def verify_app(app_id, app_secret):
    result = feishu_request('auth/v3/tenant_access_token/internal',
                            {'app_id': app_id, 'app_secret': app_secret})
    token = result.get('tenant_access_token')
    if not token:
        raise RuntimeError('飞书未返回应用令牌。')
    bot = feishu_request('bot/v3/info', token=token).get('bot', {})
    if not bot.get('open_id'):
        raise RuntimeError('请先启用飞书应用的机器人能力并发布应用。')
    return bot['open_id']


def check_ssh(port):
    try:
        with socket.create_connection(('127.0.0.1', port), timeout=3) as connection:
            connection.settimeout(3)
            return connection.recv(255).startswith(b'SSH-')
    except OSError:
        return False


def ensure_ssh(port):
    if check_ssh(port):
        ensure_ssh_autostart()
        return
    if port == 22 and shutil.which('apt-get') and shutil.which('sudo') and yes(
            '本机 SSH 尚未就绪，是否使用 sudo 安装并启动 openssh-server？'):
        subprocess.run(['sudo', 'apt-get', 'install', '-y', 'openssh-server'], check=True)
        subprocess.run(['sudo', 'systemctl', 'enable', '--now', 'ssh'], check=True)
        if check_ssh(port):
            ensure_ssh_autostart()
            return
    raise RuntimeError(f'本机 127.0.0.1:{port} 未提供 SSH，请先启动对应服务后重新执行。')


def ensure_ssh_autostart():
    service = None
    for candidate in ('ssh.service', 'sshd.service'):
        result = subprocess.run(['systemctl', 'show', candidate, '--property=LoadState', '--value'],
                                capture_output=True, text=True)
        if result.stdout.strip() == 'loaded':
            service = candidate
            break
    if service is None:
        raise RuntimeError('SSH 正在运行，但未找到可启用的 ssh.service 或 sshd.service；请配置 SSH 开机启动后重试。')
    enabled = subprocess.run(['systemctl', 'is-enabled', service], capture_output=True, text=True)
    persistent_states = {'enabled', 'linked', 'alias'}
    if enabled.returncode == 0 and enabled.stdout.strip() in persistent_states:
        return service
    command = ['sudo', 'systemctl', 'enable', service] if shutil.which('sudo') else ['systemctl', 'enable', service]
    subprocess.run(command)
    enabled = subprocess.run(['systemctl', 'is-enabled', service], capture_output=True, text=True)
    if enabled.returncode or enabled.stdout.strip() not in persistent_states:
        raise RuntimeError(f'SSH 服务未设为开机启动；请运行 `{shlex.join(command)}` 后重新执行。')
    return service


def linger_enabled(username):
    result = subprocess.run(['loginctl', 'show-user', username, '-p', 'Linger', '--value'],
                            capture_output=True, text=True)
    return result.returncode == 0 and result.stdout.strip() == 'yes'


def ensure_linger(username):
    if linger_enabled(username):
        return True
    subprocess.run(['loginctl', 'enable-linger', username])
    if linger_enabled(username):
        return True
    if shutil.which('sudo'):
        subprocess.run(['sudo', 'loginctl', 'enable-linger', username])
    return linger_enabled(username)


def verify_boot_startup(service, username):
    unit_enabled = subprocess.run(['systemctl', '--user', 'is-enabled', '--quiet', service]).returncode == 0
    unit_active = subprocess.run(['systemctl', '--user', 'is-active', '--quiet', service]).returncode == 0
    if not unit_active:
        raise RuntimeError(f'Agent 服务当前未运行。请执行 `systemctl --user start {service}` 和 `journalctl --user -u {service} -n 60` 检查。')
    linger = ensure_linger(username)
    if unit_enabled and unit_active and linger:
        print('被控端已就绪：Agent 正在运行，SSH 已就绪；已开启开机自启动，无需登录。')
        return True
    print('Agent 当前运行，但尚未确认开机后免登录启动。请执行以下命令并重新运行安装脚本验证：')
    if not unit_enabled:
        print(f'  systemctl --user enable {service}')
    if not linger:
        print(f'  sudo loginctl enable-linger {username}')
    return False


def dependencies(directory):
    venv = directory / '.venv'
    python = venv / 'bin/python'
    uv = shutil.which('uv')
    if not python.is_file():
        if uv:
            subprocess.run([uv, 'venv', '--allow-existing', '--python', sys.executable, str(venv)], check=True)
        else:
            result = subprocess.run([sys.executable, '-m', 'venv', str(venv)], capture_output=True)
            if result.returncode != 0:
                if shutil.which('apt-get') and shutil.which('sudo') and yes(
                        '缺少 Python venv，是否使用 sudo 安装 python3-venv？'):
                    subprocess.run(['sudo', 'apt-get', 'install', '-y', 'python3-venv'], check=True)
                    subprocess.run([sys.executable, '-m', 'venv', str(venv)], check=True)
                else:
                    raise RuntimeError('请安装 python3-venv 或 uv 后重新执行。')
    requirements = directory / 'requirements.txt'
    if uv:
        command = [uv, 'pip', 'install', '--python', str(python), '-r', str(requirements)]
    else:
        command = [str(python), '-m', 'pip', 'install', '--disable-pip-version-check', '-r', str(requirements)]
    subprocess.run(command, check=True)
    subprocess.run([str(python), '-c', 'import lark_oapi, lark_oapi.ws'], check=True)


def unit_text(directory, config):
    def quote(value):
        return '"' + str(value).replace('\\', '\\\\').replace('"', '\\"').replace('%', '%%') + '"'
    return ('[Unit]\nDescription=SSH Tool Feishu P2P Agent\nAfter=network-online.target\n\n'
            '[Service]\nType=simple\n'
            f'ExecStart={quote(directory / ".venv/bin/python")} {quote(directory / "agent.py")} --config {quote(config)}\n'
            f'WorkingDirectory={str(directory).replace("%", "%%")}\n'
            'Environment=PYTHONUNBUFFERED=1\nRestart=on-failure\nRestartSec=5\nTimeoutStopSec=20\n\n'
            '[Install]\nWantedBy=default.target\n')


def app_credentials(directory, old, reauthorize=False):
    saved = directory / 'registration.json'
    if reauthorize:
        print('正在重新扫码创建应用，请使用目标飞书账号，并在确认页核对所属组织。')
        credentials = {}
    elif saved.is_file():
        credentials = json.loads(saved.read_text(encoding='utf-8'))
        print('正在继续上次未完成的应用授权配置。')
    else:
        credentials = old if old.get('app_id') and old.get('app_secret') else {}
    if not credentials:
        try:
            subprocess.run([str(directory / '.venv/bin/python'), '-c', QR_REGISTRATION, str(saved)],
                           check=True, timeout=720)
        except (subprocess.CalledProcessError, subprocess.TimeoutExpired):
            raise RuntimeError('扫码授权未完成，原有服务未停止。可重试，或继续使用上次已保存的应用凭据。') from None
        credentials = json.loads(saved.read_text(encoding='utf-8'))
    else:
        print('已复用本机保存的飞书凭据，无需重新创建应用。')
    app_id, secret = credentials.get('app_id', ''), credentials.get('app_secret', '')
    if not re.fullmatch(r'cli_[A-Za-z0-9]+', app_id):
        raise RuntimeError('App ID 应为 cli_ 开头的应用 ID。')
    if not secret:
        raise RuntimeError('App Secret 不能为空。')
    return app_id, secret


def install(reauthorize=False):
    print('在被控 Linux 电脑配置飞书 P2P（自动协商）…')
    directory, config_path, unit_path = paths()
    architecture = {'x86_64': 'amd64', 'amd64': 'amd64', 'aarch64': 'arm64', 'arm64': 'arm64'}.get(platform.machine().lower())
    if not architecture:
        raise RuntimeError('目前支持 Linux x86_64 和 ARM64。')
    if subprocess.run(['systemctl', '--user', 'show-environment'], capture_output=True).returncode:
        raise RuntimeError('用户级 systemd 不可用。请用实际登录用户进入 systemd 会话后运行。')
    bundle = payload()
    old = json.loads(config_path.read_text(encoding='utf-8')) if config_path.is_file() else {}
    permissions = PERMISSIONS
    directory.mkdir(parents=True, exist_ok=True, mode=0o700)
    directory.chmod(0o700)
    permissions_path = directory / 'feishu-permissions.json'
    write_private_json(permissions_path, permissions)
    # Prepare authorization dependencies without stopping an existing Agent.
    requirements = directory / 'requirements.txt'
    requirements.write_bytes(bundle['requirements.txt'])
    requirements.chmod(0o600)
    dependencies(directory)
    port = old.get('ssh_port', 22)
    ensure_ssh(port)
    app_id, secret = app_credentials(directory, old, reauthorize)
    name = old.get('device_name', socket.gethostname())
    if not 1 <= len(name) <= 80:
        raise RuntimeError('电脑名称需要 1–80 个字符。')
    print('正在校验飞书应用…（不会发送飞书消息）')
    try:
        bot_id = verify_app(app_id, secret)
    except RuntimeError:
        print(f'请在 https://open.feishu.cn/app/{app_id} 启用机器人并发布应用，再重新执行脚本；已保存的授权会复用。')
        raise
    state_path = directory / 'owner.json'
    same_app = old.get('app_id') == app_id
    keep_owner = state_path.is_file() and same_app
    binding_code = secrets.token_urlsafe(24)
    config = {'app_id': app_id, 'app_secret': secret, 'device_name': name,
              'device_id': old.get('device_id') or uuid.uuid4().hex,
              'ssh_port': port, 'helper_path': str(directory / 'p2p-agent'),
              'feishu_auto': True,
              'state_path': str(state_path),
              'pairing_key': old['pairing_key'] if same_app and old.get('pairing_key') else secrets.token_hex(32),
              'bind_token_hash': old['bind_token_hash'] if same_app and old.get('bind_token_hash') else hashlib.sha256(binding_code.encode()).hexdigest()}
    subprocess.run(['systemctl', '--user', 'stop', SERVICE], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    if not keep_owner and state_path.exists():
        state_path.unlink()
    for name, data in [('agent.py', bundle['agent.py']), ('feishu_auto.py', bundle['feishu_auto.py']), ('requirements.txt', bundle['requirements.txt']),
                       ('p2p-agent', bundle[f'p2p-agent-{architecture}']), ('LICENSE.pion', bundle['LICENSE.pion'])]:
        target = directory / name
        temporary = target.with_name(target.name + '.new')
        temporary.write_bytes(data)
        temporary.chmod(0o700 if name == 'p2p-agent' else 0o600)
        temporary.replace(target)
    write_private_json(config_path, config)
    (directory / 'registration.json').unlink(missing_ok=True)
    profile = {key: config[key] for key in ('device_id', 'device_name', 'ssh_port', 'pairing_key')}
    profile.update({'version': 1, 'app_id': app_id, 'bot_open_id': bot_id, 'username': getpass.getuser()})
    profile['security_notice'] = ('包含设备配对密钥，可用于签署设备连接请求；仅导入可信控制端，勿公开或粘贴到聊天；'
                                 '仍需飞书应用凭据及 Linux SSH 认证。')
    owner_state = json.loads(state_path.read_text(encoding='utf-8')) if state_path.is_file() else {}
    for key in ('owner_open_id', 'chat_id'):
        if owner_state.get(key):
            profile[key] = owner_state[key]
    write_private_json(directory / 'client-profile.json', profile)
    unit_path.parent.mkdir(parents=True, exist_ok=True)
    unit_path.write_text(unit_text(directory, config_path), encoding='utf-8')
    unit_path.chmod(0o600)
    subprocess.run(['systemctl', '--user', 'daemon-reload'], check=True)
    subprocess.run(['systemctl', '--user', 'enable', SERVICE], check=True)
    subprocess.run(['systemctl', '--user', 'restart', SERVICE], check=True)
    time.sleep(1)
    user = getpass.getuser()
    verify_boot_startup(SERVICE, user)
    if not keep_owner:
        print(f'\n先完成飞书设置：https://open.feishu.cn/app/{app_id}')
        print('  1. 确认扫码页申请的三项应用权限；权限清单可直接导入：')
        print(f'     {permissions_path}')
        print('  2. 事件与回调 → 长连接 → 订阅 im.message.receive_v1 → 发布应用。')
        print('  3. 用控制端的飞书账号打开机器人私聊，发送一次绑定指令：')
        print(f'  /pair {binding_code}')
        print('     收到“配对成功”后，再执行下面的 Mac 步骤。')
    else:
        print('设备绑定已完成；已生效的飞书权限无需重复配置。')
    print('\n接下来在控制端操作（已经配置好的连接可直接使用）：')
    print('1. 将下面这个配对文件安全复制到控制端（电脑或手机）：')
    print(f'   {directory / "client-profile.json"}')
    print('2. App 新建／编辑连接 → 飞书 P2P（自动协商）→ 导入设备配对文件，选择 client-profile.json。')
    print('3. 首次点击“获取飞书应用凭据”并扫码；已有凭据则跳过，不重复申请飞书权限。')
    print(f'4. SSH 用户名填写 {user}，密码填写这台 Linux 电脑对应账号的 SSH 密码，然后保存并连接。')
    print('注意：配对文件含设备密钥，请勿公开或转发；仍需飞书凭据和 SSH 认证。')
    print(f'\nLinux 配置目录：{config_path.parent}')
    print(f'Linux 私密配置（留在本机，不导入 App）：{config_path}')
    print('详细说明：--guide  |  运行状态：--status  |  连接失败查日志：--logs')


def print_guide():
    directory, config_path, _ = paths()
    print('运行位置与自启动')
    print('  在被控 Linux 电脑执行脚本；Agent 运行在本机，不在飞书服务器。保持本机开机联网。')
    print('  脚本默认配置 Agent、SSH 开机启动及退出登录后继续运行，并检查实际状态。')
    print('飞书权限（首次配置并发布一次，已有权限无需重复配置）')
    print('  im:message.p2p_msg:readonly：接收机器人私聊消息。')
    print('  im:message:send_as_bot：机器人发送消息。')
    print('  im:message:readonly：读取应用可访问的消息，用于自动协商。')
    print('  首次扫码只预填这些权限及 im.message.receive_v1 事件，仍需确认并发布。')
    print('  不申请通讯录、文件或群聊相关独立权限；请核对飞书确认页的实际权限范围。')
    print(f'  权限导入清单（不含凭据）：{directory / "feishu-permissions.json"}')
    print('Mac 首次连接')
    print(f'  将 {directory / "client-profile.json"} 安全复制到 Mac，在 App 的飞书 P2P 连接中导入。')
    print('  点击“获取飞书应用凭据”扫码一次，再填写 Linux SSH 账号并保存连接；已有凭据无需重复扫码。')
    print('  Linux 的凭据不会自动写入 Mac；Mac 不申请新增权限，之后复用已保存的凭据。')
    print('  “飞书凭据已保存”仅表示本机已有凭据，不证明飞书权限已发布，也不代替 SSH 认证或 P2P 许可。')
    print('配对文件安全')
    print(f'  {directory / "client-profile.json"} 含 pairing_key，可签署设备连接请求。')
    print('  仅导入可信控制端，勿公开、提交 Git 或发到聊天；它不含 App Secret 或 SSH 密码。')
    print('  目录权限 700、文件权限 600；复制到其他位置时可能不保留这些权限。')
    print(f'  {config_path} 含 App Secret 和设备密钥，仅供 Linux 本机使用。')
    print(f'  泄漏时先执行：systemctl --user disable --now {SERVICE}')
    print('  再运行安装脚本 --reauthorize 创建新应用并更换密钥，重新绑定、向所有控制端导入新文件。')
    print('管理命令：--status 查看状态，--logs 查看日志，--stop 停止，--start 启动。')


def main():
    parser = argparse.ArgumentParser(prog='install-feishu-p2p.sh', description='飞书 P2P 电脑端交互安装向导；请以普通用户运行。')
    group = parser.add_mutually_exclusive_group()
    for flag, help_text in {
        'configure': '重新配置并重启服务（不传参数也是安装/配置）',
        'status': '查看电脑端服务状态', 'logs': '跟踪服务日志',
        'stop': '停止当前服务', 'start': '启动已安装的服务',
        'permissions': '输出三项权限的飞书导入 JSON',
        'guide': '查看权限、配置步骤和配对文件安全说明',
    }.items():
        group.add_argument('--' + flag, action='store_true', help=help_text)
    parser.add_argument('--reauthorize', action='store_true', help='重新扫码创建应用；成功后更换绑定，适合更换飞书账号／组织')
    parser.add_argument('--enable-auto', action='store_true', help='兼容旧命令；自动协商现已默认启用')
    args = parser.parse_args()
    if (args.reauthorize or args.enable_auto) and any((args.status, args.logs, args.stop, args.start, args.permissions, args.guide)):
        parser.error('--reauthorize 和 --enable-auto 只能用于安装/配置。')
    if args.guide:
        print_guide()
        return
    if args.permissions:
        print(json.dumps(PERMISSIONS, ensure_ascii=False, indent=2))
        return
    if sys.platform != 'linux' or sys.version_info < (3, 9):
        raise SystemExit('需要 Linux 和 Python 3.9+。')
    if os.geteuid() == 0:
        raise SystemExit('请以实际使用 Codex/SSH 的普通用户运行，不要 sudo 整个安装脚本。')
    if not shutil.which('systemctl'):
        raise SystemExit('需要支持用户服务的 systemd。')
    os.umask(0o077)
    if args.status:
        raise SystemExit(subprocess.run(['systemctl', '--user', 'status', SERVICE, '--no-pager']).returncode)
    if args.logs:
        raise SystemExit(subprocess.run(['journalctl', '--user', '-u', SERVICE, '-f']).returncode)
    if args.stop or args.start:
        subprocess.run(['systemctl', '--user', 'start' if args.start else 'stop', SERVICE], check=True)
        return
    if not sys.stdin.isatty():
        raise SystemExit('请先下载脚本，在交互终端中执行 bash install-feishu-p2p.sh；不要用 curl | bash 配置。')
    try:
        install(reauthorize=args.reauthorize)
    except (RuntimeError, OSError, ValueError, subprocess.CalledProcessError) as error:
        raise SystemExit(str(error)) from None
    except (KeyboardInterrupt, EOFError):
        raise SystemExit('\n已取消配置。') from None


if __name__ == '__main__':
    main()

SSH_TOOL_FEISHU_INSTALLER_PY
